import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SimpleRegression#getSumSquaredErrors.
 */
public class SimpleRegression_getSumSquaredErrors_TriageGen1Test {

    private SimpleRegression regression;

    @Before
    public void setUp() {
        regression = new SimpleRegression();
    }



    @Test
    public void testGetSumSquaredErrorsWithErrors() {
        // Points with some error
        regression.addData(1.0, 2.0);
        regression.addData(2.0, 3.0);
        regression.addData(3.0, 5.0); // Deviation here

        // Manual Calculation:
        // n=3, sumX=6, sumY=10, sumXX=14, sumYY=38, sumXY=23
        // Slope (b) = (n*sumXY - sumX*sumY) / (n*sumXX - sumX^2)
        // b = (3*23 - 6*10) / (3*14 - 36) = (69-60) / (42-36) = 9/6 = 1.5
        // Intercept (a) = (sumY - b*sumX)/n = (10 - 1.5*6)/3 = (10-9)/3 = 0.333333333
        // SSE = sum(y^2) - a*sum(y) - b*sum(xy)
        // SSE = 38 - (0.333333333 * 10) - (1.5 * 23)
        // SSE = 38 - 3.33333333 - 34.5 = 0.166666667

        Assert.assertEquals(0.1666666666666667, regression.getSumSquaredErrors(), 1e-10);
    }






}

