import org.apache.commons.math.distribution.TDistribution;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SimpleRegression#getSumSquaredErrors.
 */
public class SimpleRegression_getSumSquaredErrors_TriageGen1Test {

    private SimpleRegression regression;

    @Before
    public void setUp() {
        regression = new SimpleRegression();
    }









    @Test
    public void testGetSumSquaredErrorsNegativeResultClampedToZero() {
        // This test targets the Math.max(0d, ...) branch.
        // To trigger a negative value inside the max, we need sumYY - sumXY*sumXY + sumXX < 0.
        // This is mathematically impossible for real numbers in a valid regression, 
        // but floating point inaccuracies could trigger it.
        // However, we can attempt to force a scenario with extreme values.

        // Actually, the formula `sumYY - sumXY*sumXY + sumXX` in the prompt 
        // seems to be a simplified/specific version. 
        // In standard regression: SSE = sumYY - a*sumY - b*sumXY.
        // The provided code is: sumYY - sumXY * sumXY + sumXX.
        // Let's test with values that might cause precision issues.
        regression.addData(1e15, 1e15);
        regression.addData(1e15 + 1, 1e15 + 1);

        double sse = regression.getSumSquaredErrors();
        Assert.assertTrue(sse >= 0.0);
    }
}
